function key(uid,kind){return `central-v6:${kind}:${uid}`}
function goalDone(uid){return localStorage.getItem(key(uid,'done'))==='1'}
function setDone(uid,v){localStorage.setItem(key(uid,'done'),v?'1':'0')}
function subjStats(s){
 if(s.id==='pt'){
   const total=PT_CONFIG.weeks.length*7;
   let done=0;
   PT_CONFIG.weeks.forEach(w=>w.days.forEach(d=>{if(ptDayDone(w.week,d.day))done++}));
   return {total,done,pct:total?Math.round(done/total*100):0,unit:'dias'};
 }
 if(s.id==='cf'){
   const total=CF_WEEKS.length,done=CF_WEEKS.filter(w=>cfWeekPct(w)===100).length;
   return {total,done,pct:total?Math.round(done/total*100):0,unit:'m√≥dulos'};
 }
 if(s.id==='penal'){
   const total=PENAL_WEEKS.length,done=PENAL_WEEKS.filter(w=>penalWeekPct(w)===100).length;
   return {total,done,pct:total?Math.round(done/total*100):0,unit:'m√≥dulos'};
 }
 if(s.id==='cpc'){
   const total=CPC_WEEKS.length,done=CPC_WEEKS.filter(w=>cpcWeekPct(w)===100).length;
   return {total,done,pct:total?Math.round(done/total*100):0,unit:'m√≥dulos'};
 }
 if(s.id==='civil'){
   const st=civilCourseStats();return {total:st.total,done:st.done,pct:st.pct,unit:'m√≥dulos'};
 }
 const total=s.topics.length,done=s.topics.filter(t=>goalDone(t.uid)).length;
 return {total,done,pct:total?Math.round(done/total*100):0,unit:(s.id==='trab'||s.id==='ptra')?'aulas':'metas'};
}
