function renderContinue(){const x=JSON.parse(localStorage.getItem('central-v6:last')||'null');if(!x){$('continueBox').innerHTML='<div class="muted small">Nenhuma sess√£o recente.</div>';return}const act=x.tool==='vade-mecum'?`openVadeMecum()`:x.tool==='lei-seca-enxuta'?`openLeiSecaEnxuta()`:x.civilModule?`openCivilLast('${x.civilModule}')`:x.cfWeek?`openCfLast('${x.cfWeek}')`:x.penalWeek?`openPenalLast('${x.penalWeek}')`:x.cpcWeek?`openCpcLast('${x.cpcWeek}')`:x.ptWeek?`openPtLast(${x.ptWeek},${x.ptDay})`:x.topicUid?`openTopicFromLast('${x.topicUid}')`:`openInternal('${escJs(x.url)}','${escJs(x.title)}')`;$('continueBox').innerHTML=`<b style="display:block;font-size:12px">${esc(x.title)}</b><span class="muted small">${new Date(x.at).toLocaleString('pt-BR')}</span><div style="margin-top:9px"><button class="btn primary sm" onclick="${act}">Continuar</button></div>`}
